import "harbor/options.proto";

service Accounts {
  rpc GetUser (GetUserRequest) returns (GetUserReply) {
    option (harbor.handler) = "harbor.accounts:load_account";
  }
  rpc CountUsers (CountUsersRequest) returns (CountUsersReply) {
    option (harbor.handler) = "harbor.accounts:fetch_user_count";
  }
}

