syntax = "proto3";
package harbor.billing;
import "harbor/options.proto";

service Billing {
  rpc GetPayer (GetPayerRequest) returns (GetPayerReply) {
    option (harbor.handler) = "harbor.accounts:load_account";
  }
  rpc ListInvoices (ListInvoicesRequest) returns (ListInvoicesReply) {
    option (harbor.handler) = "harbor.invoices.store:list_all";
  }
}

arguments.command:
python3 - <<'EOF'
import pathlib, re, subprocess
# verify every changed py file actually changed a relevant token
out = subprocess.check_output(["git","diff","--name-only","--","harbor","tests"], text=True).split()
bad=[]
for f in out:
    for line in subprocess.check_output(["git","diff","-U0","--",f], text=True).splitlines():
        if line[:1] in "+-" and not line.startswith(("+++","---")):
            if not re.search(r'fetch_user|load_account|include_deleted|with_deleted', line):
                bad.append((f,line))
print("non-rename diff lines:", bad[:10], "count", len(bad))
# verify kept files with only comments/metrics unchanged
keep = [p for p in pathlib.Path("harbor").rglob("*.py") if "fetch_user" in p.read_text() and "load_account" not in p.read_text()]
print("files still containing fetch_user but no load_account:", len(keep))
for p in keep[:8]: print(" ", p)
EOF

